function normNutri(s) {
  return s.toLowerCase()
    .replace(/[àáâä]/g,'a').replace(/[èéêë]/g,'e')
    .replace(/[ìíîï]/g,'i').replace(/[òóôö]/g,'o')
    .replace(/[ùúûü]/g,'u')
    .replace(/[^a-z0-9\s]/g,' ')
    .replace(/\s+/g,' ').trim()
}

// Jaccard similarity su parole
function jaccard(a, b) {
  const wa = new Set(a.split(' ').filter(w => w.length >= 3))
  const wb = new Set(b.split(' ').filter(w => w.length >= 3))
  if (!wa.size || !wb.size) return 0
  const inter = [...wa].filter(w => wb.has(w)).length
  const union = new Set([...wa, ...wb]).size
  return inter / union
}

// Cerca il miglior match nutrizionale per un nome ingrediente
// Restituisce { kcal, prot, carb, zucc, fibr, gsat, sodio } o null
export function lookupNutri(nome) {
  const k = normNutri(nome)
  // Prima cerca match esatto
  const exact = NUTRI_DB.find(e => e.k === k)
  if (exact) return exact
  // Poi cerca per parole chiave (Jaccard >= 0.5)
  let best = null, bestScore = 0
  for (const e of NUTRI_DB) {
    const score = jaccard(k, e.k)
    if (score > bestScore) { bestScore = score; best = e }
  }
  return bestScore >= 0.4 ? best : null
}

// Calcola valori nutrizionali per porzione di una ricetta
// recipe: [{ ingId, qty, unit }], ings: array ingredienti magazzino
export function calcolaNutriPorzione(recipe, ings) {
  let tot = { kcal: 0, prot: 0, carb: 0, zucc: 0, fibr: 0, gsat: 0, sodio: 0 }
  let trovati = 0
  for (const r of recipe) {
    const ing = ings.find(i => i.id === r.ingId)
    if (!ing) continue
    const nutri = lookupNutri(ing.name)
    if (!nutri) continue
    // Converti qty in grammi/ml
    let g = r.qty
    if (r.unit === 'kg' || r.unit === 'l') g = r.qty * 1000
    else if (r.unit === 'g' || r.unit === 'ml') g = r.qty
    else g = r.qty * 100 // pz: stima 100g
    // Calcola contributo (valori per 100g)
    const f = g / 100
    tot.kcal  += nutri.kcal * f
    tot.prot  += nutri.prot * f
    tot.carb  += nutri.carb * f
    tot.zucc  += nutri.zucc * f
    tot.fibr  += nutri.fibr * f
    tot.gsat  += nutri.gsat * f
    tot.sodio += nutri.sodio * f
    trovati++
  }
  if (trovati === 0) return null
  return {
    kcal:  Math.round(tot.kcal),
    prot:  Math.round(tot.prot * 10) / 10,
    carb:  Math.round(tot.carb * 10) / 10,
    zucc:  Math.round(tot.zucc * 10) / 10,
    fibr:  Math.round(tot.fibr * 10) / 10,
    gsat:  Math.round(tot.gsat * 10) / 10,
    sodio: Math.round(tot.sodio),
    trovati,
    totali: recipe.filter(r => ings.find(i => i.id === r.ingId)).length
  }
}
